"""Two-stage collaborative plug-in Wiener prototype with common spatial measurement."""
import argparse
from datetime import datetime,timezone
from functools import lru_cache
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_sure_feasibility import color
from study_noise_semantic_comparison import noise_model,measures
from study_noise_patch_aggregation import aggregate
from study_noise_connected_reconstruction import cases
from study_noise_collaborative_rank import PATCH


OFFSETS=np.array([(0,0)]+[(y,x) for y in range(-4,5) for x in range(-4,5) if y or x])


def dct(n):
    k=np.arange(n)[:,None];x=np.arange(n)[None,:]
    matrix=np.sqrt(2/n)*np.cos(np.pi*k*(x+.5)/n);matrix[0]/=np.sqrt(2)
    return matrix


SPATIAL=np.kron(dct(5),dct(5));GROUP=dct(17)


@lru_cache(maxsize=2)
def covariance_table(colored):
    difference=PATCH[:,None,:]-PATCH[None,:,:]
    table=np.empty((17,17,25))
    for dy in range(-8,9):
        for dx in range(-8,9):
            delta=np.abs(difference+[dy,dx])
            if colored:
                axis=np.where(delta==0,1.,np.where(delta==1,2/3,np.where(delta==2,1/6,0.)))
                cov=np.prod(axis,axis=2)
            else:cov=np.all(delta==0,axis=2).astype(float)
            table[dy+8,dx+8]=np.einsum('pi,ij,pj->p',SPATIAL,cov,SPATIAL,optimize=True)
    return table


def coefficient_variance(indices,table):
    pos=OFFSETS[indices];delta=pos[:,None,:]-pos[None,:,:]
    cov=table[delta[:,:,0]+8,delta[:,:,1]+8]
    variance=np.einsum('ka,abp,kb->pk',GROUP,cov,GROUP,optimize=True)
    if np.min(variance)<-1e-8:raise ValueError('Negative transformed variance')
    return np.maximum(variance,0.)


def filter_group(observed,pilot,truth,variance):
    if observed.shape!=(3,25,17) or pilot.shape!=observed.shape or truth.shape!=observed.shape or variance.shape!=(25,17):raise ValueError('Fixed group shapes required')
    if not all(np.isfinite(a).all() for a in (observed,pilot,truth,variance)) or np.any(variance<0):raise ValueError('Finite data/nonnegative variance required')
    raw=SPATIAL@observed@GROUP.T;guide=SPATIAL@pilot@GROUP.T
    clean=SPATIAL@truth@GROUP.T
    power=guide*guide;gain=np.ones_like(power)
    np.divide(power,power+variance[None],out=gain,where=variance[None]>0)
    output=SPATIAL.T@(gain*raw)@GROUP;signal=SPATIAL.T@(gain*clean)@GROUP
    return output,signal,dict(mean_gain=float(np.mean(gain)),dc_gains=gain[:,0,0].tolist())


def reconstruct(observed,truth,colored):
    if observed.shape!=(3,64,64) or truth.shape!=observed.shape or not np.isfinite(observed).all() or not np.isfinite(truth).all():raise ValueError('Finite three-plane64 fields required')
    base,base_signal,_=aggregate(observed,truth,noise_model(colored,False),.8)
    # Full valid pilot support14:50;no extrapolated or periodic pilot boundary.
    sums={m:np.zeros_like(observed) for m in ('raw_group','pilot_group')}
    signals={m:np.zeros_like(observed) for m in sums};counts={m:np.zeros((64,64)) for m in sums}
    gain_means={m:[] for m in sums};dc={m:[] for m in sums};cache={}
    centres=tuple(range(20,44,3))+(43,)
    for cy in centres:
        for cx in centres:
            ys=cy+OFFSETS[:,0,None]+PATCH[None,:,0];xs=cx+OFFSETS[:,1,None]+PATCH[None,:,1]
            raw_patches=observed[:,ys,xs];pilot_patches=base[:,ys-14,xs-14]
            for mode,guide in (('raw_group',raw_patches),('pilot_group',pilot_patches)):
                distance=np.mean((guide-guide[:,0:1,:])**2,axis=(0,2))
                indices=np.r_[0,np.argsort(distance[1:],kind='stable')[:16]+1]
                key=tuple(indices)
                if key not in cache:cache[key]=coefficient_variance(indices,covariance_table(colored))
                y=ys[indices];x=xs[indices]
                raw=raw_patches[:,indices,:].swapaxes(-1,-2)
                pg=pilot_patches[:,indices,:].swapaxes(-1,-2)
                clean=truth[:,y,x].swapaxes(-1,-2)
                output,signal,audit=filter_group(raw,pg,clean,cache[key])
                for c in range(3):
                    np.add.at(sums[mode][c],(y,x),output[c].T)
                    np.add.at(signals[mode][c],(y,x),signal[c].T)
                np.add.at(counts[mode],(y,x),1.)
                gain_means[mode].append(audit['mean_gain']);dc[mode].append(audit['dc_gains'])
    result={'joint_overlap':(base[:,6:30,6:30],base_signal[:,6:30,6:30],(base-base_signal)[:,6:30,6:30]),
            'identity':(observed[:,20:44,20:44].copy(),truth[:,20:44,20:44].copy(),(observed-truth)[:,20:44,20:44])}
    audits={}
    for mode in sums:
        count=counts[mode][20:44,20:44]
        if np.any(count<=0):raise ValueError('Uncovered output pixel')
        out=sums[mode][:,20:44,20:44]/count[None]
        signal=signals[mode][:,20:44,20:44]/count[None]
        result[mode]=(out,signal,out-signal)
        audits[mode]=dict(group_count=len(gain_means[mode]),mean_gain=float(np.mean(gain_means[mode])),
            mean_dc_gains=np.mean(dc[mode],axis=0).tolist(),min_contributions=float(count.min()),max_contributions=float(count.max()))
    return result,audits


def metrics(outputs,truth,identity):
    core=truth[:,20:44,20:44];results={}
    peak=None
    if identity is not None and identity['shape'] in ('gaussian','gaussian_shifted'):
        peak=np.unravel_index(np.argmax(core[identity['channel']]),(24,24))
    for mode,(out,signal,residual) in outputs.items():
        row=dict(planes=[measures(out[c],signal[c],residual[c],core[c]) for c in range(3)],
            abs_q999_per_plane=np.quantile(np.abs(out-core),.999,axis=(1,2)).tolist(),
            max_abs_error_per_plane=np.max(np.abs(out-core),axis=(1,2)).tolist())
        if identity is not None:
            c=identity['channel'];energy=float(np.mean(core[c]**2))
            row['signal_projection']=float(np.mean(signal[c]*core[c])/energy)
            if peak is not None:
                py,px=peak;target=float(core[c,py,px])
                row['sampled_peak']=dict(original_yx=[int(py+20),int(px+20)],target=target,
                    output=float(out[c,py,px]),signal=float(signal[c,py,px]),squared_error=float((out[c,py,px]-target)**2))
        results[mode]=row
    return results


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    path=ROOT/'docs/validation/raw/controle-biais-selection-bruit-v001-20261026T130217Z.json'
    digest=sha256(path);parent=json.loads(path.read_text(encoding='utf-8'))
    start=datetime.now(timezone.utc);records=[];controls=[];challenges=[];serial=0
    for colored in (False,True):
        configurations=[(None,np.full((3,64,64),level),8,level) for level in (0.,5.,20.)]
        configurations.extend((identity,truth,1,None) for identity,truth in cases())
        for identity,truth,trials,level in configurations:
            for trial in range(trials):
                seed=261026700000+serial;serial+=1
                noise=np.random.default_rng(seed).standard_normal((3,64,64))
                if colored:noise=color(noise)
                outputs,audit=reconstruct(truth+noise,truth,colored)
                row=dict(noise='binomial_correlated' if colored else 'white',seed=seed,trial=trial,audit=audit,metrics=metrics(outputs,truth,identity))
                if identity is None:controls.append(dict(level=level,**row))
                else:records.append(dict(**identity,**row))
        print('Model',colored,'54forms+24constantfields completed',flush=True)
    for r in parent['records']:
        if r['noise']!='binomial_correlated' or r['configuration']['family']!='flat':continue
        stream,_=np.random.SeedSequence(r['seed']).spawn(2)
        observed=color(np.random.default_rng(stream).standard_normal((3,64,64)));truth=np.zeros_like(observed)
        outputs,audit=reconstruct(observed,truth,True)
        challenges.append(dict(source_seed=r['seed'],audit=audit,metrics=metrics(outputs,truth,None),
            centre_squared_error={m:(out[:,12,12]**2).tolist() for m,(out,_,_) in outputs.items()}))
    if len(records)!=108 or len(controls)!=48 or len(challenges)!=9 or sha256(path)!=digest:raise ValueError('Incomplete/changed inputs')
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f"collaboratif-wiener-deux-etapes-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,
        started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),commit=git('rev-parse','HEAD'),
        local_changes=git('status','--short').splitlines(),runner_sha256=sha256(Path(__file__)),numpy_version=np.__version__,
        dependencies={n:sha256(ROOT/'tests'/n) for n in ('study_noise_sure_feasibility.py','study_noise_semantic_comparison.py','study_noise_patch_aggregation.py','study_noise_connected_reconstruction.py','study_noise_collaborative_rank.py')},
        challenge_parent=dict(path=str(path),sha256=digest),records=records,noise_controls=controls,challenges=challenges,
        rules='Pilot=jointoverlap h.8 fromSAMEobservation,valid14:50.5x5patches,17nearest rawSSD jointplanes in9x9search,raw-guide orpilot-guide ablation. Fixedorthonormal DCTspatial25/group17,perplane transforms. Wiener g=pilotcoeff^2/(pilotcoeff^2+rawcoefficientvariance),ALLcoefficientsincludingDC/no preservedgroupmean. Exactfixedgeometryvariance fromstationaryknowncovariance includespatchoverlap via spatialDCTcrosscovarianceandgroupDCT,notiidcolumns. Pilotresidualnoise NOTsubtracted or independent. AggregateALL17filteredpatches equally across81referencecentres20:43,step3+edge,output20:44(common24),positivecoveragechecked. Samegains/groups truthtransport forerror decomposition.108forms+48constantfields levels0/5/20+9knownchallenges. Peakmetrics followmaxsampledtruthinsamecore,notfixed32.',
        limitations='ExperimentalprototypeNOTfullBM3D.9search differsfromprevious21;24core differsfromprevious36/centralpoint,usecurrentcomparatorsonly.1draw per form/model exploratory,controls8perlevel/model notlargevalidation. Fixedgeometryknownvariance doesNOTcondition on observed grouping orpilotbasis/gains. Pilotsharesnoise;notindependent orclean. KnownGaussians/independentplanes notRCD. No finalnoisematching,no hyperparameterfit,production,networktraining ornewRAW.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print(output,flush=True);print(len(records),'forms,',len(controls),'constantcontrols,',len(challenges),'knownchallenges',flush=True)


if __name__=='__main__':main()
